package cognitive_lab;

import com.androidhit.lumadrift.data.EconomyCurve121;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.io.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;

/** Deterministic, bounded local hypothesis laboratory. All behavioral outcomes are modeled. */
public final class CognitiveLab {
    static final long DEFAULT_SEED=20261030L;
    static final String[] SCENARIOS={"current_model","teaching_support","reward_muted"};
    static final String[] ABLATIONS={"no_learning","no_fatigue","low_planning","reward_zero"};
    static final int CAMPAIGN_CAP=400,MAX_ACTIONS_PER_DAY=120,MAX_ATTEMPT_ACTIONS=110;
    static final int[] HELD_OUT={401,573,721,1000};
    static final class Config {int profiles=100,repetitions=30,days=8;long seed=DEFAULT_SEED;boolean smoke=false;Path output=Paths.get("docs/validation/cognitive-lab/latest");Path root=Paths.get(".").toAbsolutePath().normalize();}
    static final class Trajectory {
        String profile,scenario;int repetition,attempts,cleared,actions,blocked,undos,shellTaps,focusUses,coins=180,coinsEarned,coinsSpent,energySpent,energyRefilled,sessions;
        double sessionMinutes,overrun,knowledge,frustration,nodes;boolean d1,d7;Map<String,Integer> stopReasons=new TreeMap<>();double[] learned;
        double metric(String name){switch(name){case "completionRate":return attempts==0?0:(double)cleared/attempts;case "meanLevelsCleared":return cleared;case "meanActions":return actions;case "blockedRate":return actions==0?0:(double)blocked/actions;case "meanSessionMinutes":return sessions==0?0:sessionMinutes/sessions;case "modeledD1":return d1?1:0;case "modeledD7":return d7?1:0;case "meanOverrunMinutes":return sessions==0?0:overrun/sessions;case "meanKnowledge":return knowledge;default:throw new IllegalArgumentException(name);}}
        void stop(String reason){stopReasons.merge(reason,1,Integer::sum);}
        Map<String,Object> json(){return Json.obj("profileId",profile,"repetition",repetition,"scenario",scenario,"attempts",attempts,"levelsCleared",cleared,"actions",actions,"blocked",blocked,"undos",undos,"shellTaps",shellTaps,"focusUses",focusUses,"modeledD1",d1,"modeledD7",d7,"sessions",sessions,"modeledSessionMinutes",sessionMinutes,"modeledOverrunMinutes",overrun,"coinsStart",180,"coinsEarned",coinsEarned,"coinsSpent",coinsSpent,"coinsEnd",coins,"energySpent",energySpent,"energyRefilled",energyRefilled,"meanKnowledge",knowledge,"finalFrustration",frustration,"searchNodes",nodes,"stopReasons",stopReasons);}
    }
    static final class Outputs implements AutoCloseable {
        final BufferedWriter levels,trajectories;final List<Object> traces=new ArrayList<>();final Map<String,Integer> traceCounts=new HashMap<>();
        Outputs(Path out)throws IOException{Files.createDirectories(out);levels=writer(out.resolve("level-results.csv.gz"));trajectories=writer(out.resolve("trajectories.csv.gz"));levels.write("profileId,repetition,scenario,attempt,level,startDay,endDay,outcome,actions,exits,blocked,undos,shellTaps,focusRequests,focusUses,paidUndoCoins,budgetUsed,budgetRemaining,remaining,modeledSeconds,stars,coachCueObservations,deadEndWarningObservations,focusCueObservations\n");trajectories.write("profileId,repetition,scenario,attempts,levelsCleared,actions,blocked,undos,shellTaps,focusUses,modeledD1,modeledD7,sessions,modeledSessionMinutes,modeledOverrunMinutes,coinsStart,coinsEarned,coinsSpent,coinsEnd,energySpent,energyRefilled,meanKnowledge,finalFrustration,searchNodes,stopReasons\n");}
        static BufferedWriter writer(Path path)throws IOException{return new BufferedWriter(new OutputStreamWriter(new GZIPOutputStream(Files.newOutputStream(path)),StandardCharsets.UTF_8));}
        static void csv(BufferedWriter writer,Map<String,Object> data)throws IOException{boolean first=true;for(Object v:data.values()){if(!first)writer.write(',');first=false;String s=v instanceof Map?Json.encode(v):String.valueOf(v);if(s.contains(",")||s.contains("\"")||s.contains("\n")){writer.write('"');writer.write(s.replace("\"","\"\""));writer.write('"');}else writer.write(s);}writer.write('\n');}
        public void close()throws IOException{levels.close();trajectories.close();}
    }
    static long mix(long seed,long... values){long x=seed;for(long value:values){x^=value+0x9e3779b97f4a7c15L+(x<<6)+(x>>>2);x=(x^(x>>>30))*0xbf58476d1ce4e5b9L;x=(x^(x>>>27))*0x94d049bb133111ebL;x^=x>>>31;}return x;}
    static Random random(Config c,Profile p,int repetition,long... keys){long h=mix(c.seed,p.id.hashCode(),repetition);return new Random(mix(h,keys));}
    static double rewardScale(String scenario){return scenario.equals("reward_muted")?.15:scenario.equals("reward_zero")?0:1;}
    static double duration(Profile p,CognitiveAgent agent,CognitiveAgent.Decision d,Random rng){return Math.max(1.2,(2.4+d.nodes*.022+(1-agent.meanKnowledge())*3.5)*(1+agent.fatigue*.35)*(.8+.4*rng.nextDouble()));}
    static double startUtility(Profile p,CognitiveAgent agent,double recentSuccess,double recentReward,String scenario){return -.4+.95*p.puzzleInterest+.20*p.explorationInterest+.14*p.collectionInterest*rewardScale(scenario)+.32*recentSuccess+.36*p.rewardSensitivity*recentReward*rewardScale(scenario)-.65*agent.frustration-.24*agent.fatigue;}
    static double continueUtility(Profile p,CognitiveAgent agent,double fraction,double recentSuccess,double recentReward,String scenario){return .18+.65*p.puzzleInterest+.15*p.explorationInterest+.45*p.rewardSensitivity*recentReward*rewardScale(scenario)+.22*recentSuccess-.80*agent.frustration-.45*agent.fatigue-.52*fraction;}
    static double sigmoid(double value){return 1/(1+Math.exp(-value));}
    static Trajectory run(Config c,Profile p,int rep,String scenario,Outputs output,boolean record)throws IOException {
        Trajectory t=new Trajectory();t.profile=p.id;t.repetition=rep;t.scenario=scenario;CognitiveAgent agent=new CognitiveAgent(p,scenario);Environment.Energy energy=new Environment.Energy();Environment attempt=null;
        int level=1,ordinal=0;double recentSuccess=0,recentReward=0;
        for(int day=0;day<c.days;day++){
            if(day>0)agent.overnight();Random availability=random(c,p,rep,day,111);double planned=p.timeAvailabilityMinutes*(.65+.7*availability.nextDouble());boolean available=day==0||availability.nextDouble()<.72+.20*Math.min(1,p.timeAvailabilityMinutes/26);
            double desire=startUtility(p,agent,recentSuccess,recentReward,scenario);boolean returns=day==0||(available&&random(c,p,rep,day,112).nextDouble()<sigmoid(desire*2.4));
            if(!returns){t.stop(available?"modeled_return_utility":"exogenous_unavailability");continue;}
            double elapsed=0;int dayActions=0,failures=0;String stop="day_action_cap";
            while(dayActions<MAX_ACTIONS_PER_DAY&&level<=CAMPAIGN_CAP){
                double clock=day*86400+18*3600+elapsed*60;energy.refresh(clock);
                if(attempt==null){if(!energy.reserve(level,clock)){stop="energy_empty";break;}attempt=new Environment(level,++ordinal,day);t.attempts++;
                    if(scenario.equals("teaching_support")&&(level==1||level==11))elapsed+=.2;}
                if(attempt.budget.isExhausted()){if(record&&output!=null)Outputs.csv(output.levels,attempt.row(p.id,rep,scenario,day,"budget_exhausted"));attempt=null;failures++;agent.frustration=Math.min(2,agent.frustration+.16*p.frustrationSensitivity);recentSuccess=-1;stop="budget_exhausted";if(failures>=3)break;continue;}
                CognitiveAgent.Observation observation=attempt.observation(clock,t.coins);
                int actionIndex=attempt.actions;double[] knowledgeBefore=agent.knowledge.clone();double fatigueBefore=agent.fatigue,frustrationBefore=agent.frustration;int budgetUsedBefore=attempt.budget.used();Random decisionRng=random(c,p,rep,day,level,attempt.ordinal,actionIndex,222);CognitiveAgent.Decision decision=agent.choose(observation,decisionRng);
                double seconds=duration(p,agent,decision,random(c,p,rep,day,level,attempt.ordinal,attempt.actions,223));Environment.Result result=attempt.apply(decision,observation,clock,seconds);dayActions++;elapsed+=seconds/60;t.actions++;t.coins-=result.coinCost;t.coinsSpent+=result.coinCost;
                agent.feedback(observation,decision.action,result.kind,result.reason,seconds);
                if(result.kind.equals("undo")){int restored=findRestored(observation.present,attempt.board.remainingMask());if(restored>=0)agent.remember(attempt.board.remainingMask(),attempt.board.gateMask(),restored);}
                if(result.kind.equals("blocked"))t.blocked++;if(result.kind.equals("undo"))t.undos++;if(result.kind.equals("shell"))t.shellTaps++;if(result.kind.equals("focus_visible"))t.focusUses++;
                if(output!=null&&record&&rep==0&&Integer.parseInt(p.id.substring(1))<=4&&output.traceCounts.getOrDefault(scenario,0)<100&&(level<=2||level==11||result.kind.equals("blocked")||result.kind.equals("focus_visible"))){output.traceCounts.merge(scenario,1,Integer::sum);output.traces.add(Json.obj("profileId",p.id,"repetition",rep,"scenario",scenario,"day",day,"level",level,"attempt",attempt.ordinal,"step",attempt.actions,"decisionSeed",Long.toString(mix(mix(c.seed,p.id.hashCode(),rep),day,level,attempt.ordinal,actionIndex,222)),"cognitiveBefore",Json.obj("knowledge",knowledgeBefore,"fatigue",fatigueBefore,"frustration",frustrationBefore),"observation",Json.obj("remaining",Long.bitCount(observation.present),"presentMask",Long.toString(observation.present),"gates",observation.gates,"shellLayers",sum(observation.shells),"shellLayersById",observation.shells,"budgetUsed",budgetUsedBefore,"visibleHint",observation.visibleHint,"cueSource",observation.cueSource,"deadEndWarning",observation.deadEndWarning,"budgetRemaining",observation.remainingBudget),"decision",decision.json(),"outcome",Json.obj("kind",result.kind,"success",result.kind.equals("exit")||result.kind.equals("shell"),"blockedReason",result.reason,"budgetUsed",attempt.budget.used(),"budgetRemaining",attempt.budget.remaining(),"remaining",attempt.board.remainingCount(),"presentMask",Long.toString(attempt.board.remainingMask()),"gates",attempt.board.gateMask(),"knowledge",agent.knowledge.clone(),"fatigue",agent.fatigue,"frustration",agent.frustration,"modeledSeconds",seconds)));}
                if(attempt.board.isSolved()){t.cleared++;int reward=EconomyCurve121.campaignReward(level,attempt.stars());t.coins+=reward;t.coinsEarned+=reward;recentSuccess=.7*recentSuccess+.3;recentReward=.65*recentReward+.35*Math.min(1,reward/60d);agent.frustration*=.65;
                    if(record&&output!=null)Outputs.csv(output.levels,attempt.row(p.id,rep,scenario,day,"completed"));attempt=null;level++;}
                else if(result.kind.equals("give_up")||attempt.actions>=MAX_ATTEMPT_ACTIONS){if(record&&output!=null)Outputs.csv(output.levels,attempt.row(p.id,rep,scenario,day,result.kind.equals("give_up")?"agent_give_up":"attempt_action_cap"));attempt=null;failures++;recentSuccess=.7*recentSuccess-.3;recentReward*=.6;if(failures>=3){stop="repeated_attempt_failures";break;}}
                double utility=continueUtility(p,agent,elapsed/planned,recentSuccess,recentReward,scenario);
                if(elapsed>=planned*(1.12+.45*p.rewardSensitivity*rewardScale(scenario))){stop="availability_hard_limit";break;}
                if(dayActions>=4&&random(c,p,rep,day,dayActions,333).nextDouble()>sigmoid(utility*3.5)&&((dayActions%5)==0||attempt==null)){stop=elapsed>=planned?"utility_stop_after_planned_time":"utility_stop";break;}
            }
            if(level>CAMPAIGN_CAP)stop="administrative_campaign_scope_cap";t.stop(stop);if(dayActions>0){t.sessions++;if(day==1)t.d1=true;if(day==7)t.d7=true;t.sessionMinutes+=elapsed;t.overrun+=Math.max(0,elapsed-planned);}if(level>CAMPAIGN_CAP)break;
        }
        if(attempt!=null&&record&&output!=null)Outputs.csv(output.levels,attempt.row(p.id,rep,scenario,c.days-1,"horizon_censored"));
        t.knowledge=agent.meanKnowledge();t.frustration=agent.frustration;t.nodes=agent.totalNodes;t.learned=agent.knowledge.clone();t.energySpent=energy.spent;t.energyRefilled=energy.refilled;
        if(t.coins!=180+t.coinsEarned-t.coinsSpent||t.coins<0)throw new AssertionError("Coin conservation");if(record&&output!=null)Outputs.csv(output.trajectories,t.json());return t;
    }
    static int findRestored(long before,long after){long added=after&~before;return added==0?-1:Long.numberOfTrailingZeros(added);}
    static int sum(int[] values){int n=0;for(int value:values)n+=value;return n;}
    static String[] METRICS={"completionRate","meanLevelsCleared","meanActions","blockedRate","meanSessionMinutes","modeledD1","modeledD7","meanOverrunMinutes","meanKnowledge"};
    static Map<String,Object> aggregate(String id,List<Trajectory> values){Map<String,Object> out=Json.obj("id",id,"label",label(id),"trajectories",values.size());for(String metric:METRICS){double total=0;for(Trajectory t:values)total+=t.metric(metric);out.put(metric,values.isEmpty()?0:total/values.size());}
        int attempts=0,cleared=0,actions=0,blocked=0,sessions=0,focus=0,shells=0,coins=0,energy=0;Map<String,Integer> stops=new TreeMap<>();for(Trajectory t:values){attempts+=t.attempts;cleared+=t.cleared;actions+=t.actions;blocked+=t.blocked;sessions+=t.sessions;focus+=t.focusUses;shells+=t.shellTaps;coins+=t.coinsSpent;energy+=t.energySpent;for(Map.Entry<String,Integer> e:t.stopReasons.entrySet())stops.merge(e.getKey(),e.getValue(),Integer::sum);}
        out.put("totals",Json.obj("attempts",attempts,"levelsCleared",cleared,"actions",actions,"blocked",blocked,"sessions",sessions,"earnedFocusUses",focus,"shellTaps",shells,"coinsSpent",coins,"energySpent",energy));out.put("stopReasons",stops);return out;}
    static String label(String id){switch(id){case "current_model":return "Current modeled journey";case "teaching_support":return "Hypothetical teaching support";case "reward_muted":return "Hypothetical muted reward salience";default:return id.replace('_',' ');}}
    static Map<String,Object> compare(String scenario,List<Trajectory> base,List<Trajectory> target,long seed){if(base.size()!=target.size())throw new AssertionError("Pair count");Map<String,Object> metrics=new LinkedHashMap<>();
        for(String metric:METRICS){Map<String,List<Double>> clusters=new TreeMap<>();double total=0;for(int i=0;i<base.size();i++){Trajectory a=base.get(i),b=target.get(i);if(!a.profile.equals(b.profile)||a.repetition!=b.repetition)throw new AssertionError("Unmatched pair");double delta=b.metric(metric)-a.metric(metric);total+=delta;clusters.computeIfAbsent(a.profile,k->new ArrayList<>()).add(delta);}
            List<Double> means=new ArrayList<>();for(List<Double> cluster:clusters.values()){double n=0;for(double v:cluster)n+=v;means.add(n/cluster.size());}double[] samples=new double[1000];Random rng=new Random(mix(seed,metric.hashCode()));for(int b=0;b<samples.length;b++){double n=0;for(int j=0;j<means.size();j++)n+=means.get(rng.nextInt(means.size()));samples[b]=n/means.size();}Arrays.sort(samples);
            metrics.put(metric,Json.obj("meanDifference",total/Math.max(1,base.size()),"ci95",new double[]{samples[24],samples[974]},"pairs",base.size(),"profileClusters",means.size()));}
        return Json.obj("scenario",scenario,"baseline","current_model","metrics",metrics,"intervalMethod","1000 resamples of whole-profile mean paired differences; synthetic cohort sensitivity, not human population inference");}
    static Map<String,Object> transfer(Config c,List<Profile> profiles,List<Trajectory> training)throws IOException {
        List<Object> rows=new ArrayList<>();double trained=0,cold=0,trainedBlocked=0,coldBlocked=0;int probes=0;
        for(Trajectory t:training){Profile p=profiles.get(Integer.parseInt(t.profile.substring(1))-1);for(int number:HELD_OUT){boolean[] success=new boolean[2];int[] blocks=new int[2];for(int condition=0;condition<2;condition++){
                    CognitiveAgent agent=new CognitiveAgent(p,"current_model");if(condition==1)System.arraycopy(t.learned,0,agent.knowledge,0,5);Environment env=new Environment(number,1,0);int coins=180;
                    while(!env.board.isSolved()&&!env.budget.isExhausted()&&env.actions<MAX_ATTEMPT_ACTIONS){CognitiveAgent.Observation obs=env.observation(env.seconds,coins);CognitiveAgent.Decision d=agent.choose(obs,random(c,p,t.repetition,number,env.actions,701));Environment.Result r=env.apply(d,obs,env.seconds,duration(p,agent,d,random(c,p,t.repetition,number,env.actions,702)));coins-=r.coinCost;agent.feedback(obs,d.action,r.kind,r.reason,r.seconds);if(r.kind.equals("undo")){int restored=findRestored(obs.present,env.board.remainingMask());if(restored>=0)agent.remember(env.board.remainingMask(),env.board.gateMask(),restored);}if(r.kind.equals("give_up"))break;}
                    success[condition]=env.board.isSolved();blocks[condition]=env.blocked;}
                probes++;cold+=success[0]?1:0;trained+=success[1]?1:0;coldBlocked+=blocks[0];trainedBlocked+=blocks[1];if(t.repetition==0)rows.add(Json.obj("profileId",p.id,"level",number,"coldCompleted",success[0],"trainedCompleted",success[1],"coldBlocked",blocks[0],"trainedBlocked",blocks[1]));}}
        return Json.obj("heldOutLevels",HELD_OUT,"trainingCampaignMaximum",CAMPAIGN_CAP,"pairs",probes,"modeledColdCompletionRate",cold/probes,"modeledTrainedCompletionRate",trained/probes,"modeledCompletionDifference",(trained-cold)/probes,"meanColdBlocked",coldBlocked/probes,"meanTrainedBlocked",trainedBlocked/probes,"design","Same profile, held-out geometry, repetition and decision seeds; knowledge-only transplant from current_model; reset fatigue/frustration/memory, equal180 coins, no progression or reward utility during probe; native free Focus and warning remain available equally","sampleRows",rows);}
    static Map<String,Object> scope(){return Json.obj("kind","synthetic_local_hypothesis_lab","modeled",true,"humanParticipants",0,"clinicalAssessment",false,"humanRetentionPrediction",false,"iqCalibration",false,"campaign","Current RelayCatalog U1-U400, progressionVersion6; held-out U401/U573/U721/U1000","engine","Unmodified Board + MoveBudget policy6 + ElementalShell121 + ExitChain121 + EconomyCurve121","assistance","Native U1 first2-exit coach, rendered exact dead-end warning, and explicitly requested one-use earned Focus are environment cues; cue sources are recorded for selected traces and exposure counts are recorded for every attempt. No hidden solution, safety suffix or solver state enters agent search.","energy","Runtime-matched in-memory pacing ledger: starts10; U1-U10 free; 1 per U11+ start/retry; refill1/600 modeled seconds; capacity raises without grant. Persistence, clock rollback and purchase receipts excluded.","economy","Starts180 coins; first-clear current stars/rewards; first2 undo free then current coin price; no action refund on undo. No IAP, ads or purchased continuations.","exclusions",Arrays.asList("Companion skills and ownership/evolution/home/summon navigation are not simulated; collection/exploration interests affect declared utility only","Inventory powers, login/quest/tutorial-completion/avatar rewards, real money, ads, events and multiplayer excluded","No rendering, accessibility comprehension, touch motor behavior, actual emotion, actual IQ or addiction diagnosis","Utilities, learning and timing coefficients are explicit uncalibrated hypotheses; no human distribution or target D1/D7 fitted","One available modeled session per day; no real-time notifications or social acquisition"));}
    static Map<String,Object> configJson(Config c){return Json.obj("profiles",c.profiles,"repetitions",c.repetitions,"scenarios",Arrays.asList(SCENARIOS),"days",c.days,"seed",c.seed,"smoke",c.smoke,"campaignLevelCap",CAMPAIGN_CAP,"maxActionsPerDay",MAX_ACTIONS_PER_DAY,"maxAttemptActions",MAX_ATTEMPT_ACTIONS,"heldOutLevels",HELD_OUT,"ablationProfiles",Math.min(c.profiles,c.smoke?3:20),"ablationRepetitions",Math.min(c.repetitions,c.smoke?2:10),"command","./scripts/run-cognitive-lab.sh "+(c.smoke?"--smoke ":"")+"--profiles "+c.profiles+" --repetitions "+c.repetitions+" --seed "+c.seed,"timeUnit","Modeled seconds/minutes/days; runtime separately in provenance","rewardSalience",Json.obj("current_model",1,"teaching_support",1,"reward_muted",.15,"reward_zero",0),"teachingSupport",Json.obj("initialKnowledgeIncrement",.16,"learningRateMultiplier",1.7,"modeledExplanationSecondsAtU1AndU11",12),"utilityCoefficients",Json.obj("start","-.4+.95*puzzle+.20*exploration+.14*collection*rewardScale+.32*recentSuccess+.36*rewardSensitivity*recentReward*rewardScale-.65*frustration-.24*fatigue","continue",".18+.65*puzzle+.15*exploration+.45*rewardSensitivity*recentReward*rewardScale+.22*recentSuccess-.80*frustration-.45*fatigue-.52*elapsed/planned","returnProbability","sigmoid(2.4*startUtility) times exogenous daily availability; day0 forced","stopProbability","1-sigmoid(3.5*continueUtility), checked every5 actions or between completed boards after4 actions","hardTimeLimit","planned*(1.12+.45*rewardSensitivity*rewardScale)","modelDecisionDuration","max(1.2,(2.4+.022*nodes+3.5*(1-meanKnowledge))*(1+.35*fatigue)*Uniform(.8,1.2)) seconds"));}
    static String sha(Path file)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file));StringBuilder out=new StringBuilder();for(byte b:digest)out.append(String.format("%02x",b&255));return out.toString();}
    static Map<String,Object> sourceHashes(Config c)throws Exception{Map<String,Object> hashes=new TreeMap<>();for(String dir:new String[]{"scripts/cognitive_lab","app/src/main/java/com/androidhit/lumadrift/engine"})try(java.util.stream.Stream<Path> paths=Files.list(c.root.resolve(dir))){for(Path p:(Iterable<Path>)paths.filter(p->p.toString().endsWith(".java"))::iterator)hashes.put(c.root.relativize(p).toString(),sha(p));}for(String file:new String[]{"app/src/main/java/com/androidhit/lumadrift/data/EconomyCurve121.java","app/src/main/java/com/androidhit/lumadrift/data/SessionEnergyStore.java","app/src/main/java/com/androidhit/lumadrift/LumaView.java","scripts/run-cognitive-lab.sh"})hashes.put(file,sha(c.root.resolve(file)));return hashes;}
    public static void main(String[] args)throws Exception{
        Config c=new Config();for(int i=0;i<args.length;i++){switch(args[i]){case "--help":System.out.println("Usage: ./scripts/run-cognitive-lab.sh [--smoke] [--output DIR] [--seed LONG] [--profiles 1..100] [--repetitions 1..100]\nDefault:100 profiles x30 repetitions x3 scenarios x8 modeled days. All outcomes synthetic. --smoke:6 profiles x2 repetitions; output defaults docs/validation/cognitive-lab/latest.\nChecks: ./scripts/test-cognitive-lab.sh");return;case "--smoke":c.smoke=true;c.profiles=6;c.repetitions=2;break;case "--output":c.output=Paths.get(args[++i]);break;case "--profiles":c.profiles=Integer.parseInt(args[++i]);break;case "--repetitions":c.repetitions=Integer.parseInt(args[++i]);break;case "--seed":c.seed=Long.parseLong(args[++i]);break;case "--root":c.root=Paths.get(args[++i]).toAbsolutePath().normalize();break;default:throw new IllegalArgumentException("Unknown argument "+args[i]);}}
        int minimumToScope=0;for(int level=1;level<=CAMPAIGN_CAP;level++)minimumToScope+=com.androidhit.lumadrift.engine.RelayCatalog.get(level).tiles.size();if(minimumToScope<=c.days*MAX_ACTIONS_PER_DAY)throw new IllegalArgumentException("Campaign scope must exceed maximum possible horizon progress to avoid return censoring");
        if(c.profiles<1||c.profiles>100||c.repetitions<1||c.repetitions>100)throw new IllegalArgumentException("Profiles1..100, repetitions1..100");long started=System.nanoTime();List<Profile> profiles=Profile.generate(c.profiles,c.seed);Map<String,List<Trajectory>> runs=new LinkedHashMap<>();List<Object> scenarioSummaries=new ArrayList<>(),profileResults=new ArrayList<>(),comparisons=new ArrayList<>(),ablationComparisons=new ArrayList<>();Map<String,Object> transfer;List<Object> traces;
        try(Outputs output=new Outputs(c.output)){
            for(String scenario:SCENARIOS){List<Trajectory> rows=new ArrayList<>();for(Profile p:profiles)for(int rep=0;rep<c.repetitions;rep++)rows.add(run(c,p,rep,scenario,output,true));runs.put(scenario,rows);scenarioSummaries.add(aggregate(scenario,rows));for(Profile p:profiles){List<Trajectory> selected=new ArrayList<>();for(Trajectory t:rows)if(t.profile.equals(p.id))selected.add(t);Map<String,Object> result=aggregate(scenario,selected);result.put("profileId",p.id);result.put("scenario",scenario);profileResults.add(result);}System.out.println("Completed "+scenario+": "+rows.size()+" modeled trajectories");}
            for(int s=1;s<SCENARIOS.length;s++)comparisons.add(compare(SCENARIOS[s],runs.get("current_model"),runs.get(SCENARIOS[s]),c.seed));
            int np=Math.min(c.profiles,c.smoke?3:20),nr=Math.min(c.repetitions,c.smoke?2:10);List<Trajectory> baseline=new ArrayList<>();for(Trajectory t:runs.get("current_model"))if(Integer.parseInt(t.profile.substring(1))<=np&&t.repetition<nr)baseline.add(t);
            for(String variant:ABLATIONS){List<Trajectory> rows=new ArrayList<>();for(int i=0;i<np;i++)for(int rep=0;rep<nr;rep++)rows.add(run(c,profiles.get(i),rep,variant,null,false));Map<String,Object> comparison=compare(variant,baseline,rows,c.seed);comparison.put("summary",aggregate(variant,rows));ablationComparisons.add(comparison);}
            System.out.println("Completed matched ablations; running held-out knowledge transfer");transfer=transfer(c,profiles,runs.get("current_model"));traces=output.traces;
        }
        Map<String,Object> scope=scope(),config=configJson(c),totals=Json.obj("modeled",true,"humanParticipants",0,"trajectories",c.profiles*c.repetitions*3,"mainTrajectories",c.profiles*c.repetitions*3,"scenarioCount",3,"profileCount",c.profiles,"repetitionsPerProfile",c.repetitions,"heldOutProbePairs",transfer.get("pairs"));
        Map<String,Object> definitions=Json.obj("completionRate","Mean across trajectories of completed campaign levels / started attempts, including failed/retried/horizon-censored starts; not campaign completion","meanLevelsCleared","Mean unique sequential campaign levels cleared per trajectory, capped at400","blockedRate","Mean trajectory blocked taps/all decision interactions, including shell/Focus/Undo; not only productive exits","modeledD1","Share of synthetic trajectories with a modeled session on day1 (day0 starts forced)","modeledD7","Share of synthetic trajectories with a modeled session on day7, not continuous retention","meanSessionMinutes","Mean trajectory mean duration of modeled sessions","meanOverrunMinutes","Mean trajectory mean max(0,sessionMinutes-plannedMinutes); behavioral hypothesis, not addiction diagnosis","meanKnowledge","Mean declared five-rule knowledge state at horizon; not a psychometric score","ci95","Profile-cluster bootstrap of synthetic paired differences; no human calibration or population prediction");
        Map<String,Object> summary=Json.obj("schemaVersion",1,"scope",scope,"config",config,"totals",totals,"scenarios",scenarioSummaries,"profileResults",profileResults,"metricDefinitions",definitions);
        List<Object> profileJson=new ArrayList<>();for(Profile p:profiles)profileJson.add(p.json());Map<String,Object> profileData=Json.obj("schemaVersion",1,"generation","Independently shuffled Latin-hypercube strata per dimension; arbitrary uniform ranges, no human norming. Fictional IQ-like label separately permuted and never used in behavior.","profiles",profileJson);
        Map<String,Object> paired=Json.obj("schemaVersion",1,"modeled",true,"pairedSeeds",true,"comparisons",comparisons,"transfer",transfer,"ablations",Json.obj("design","First20 fixed synthetic profiles x first10 repetitions (smoke3x2), paired with identical current_model seeds; additional controls, not main cohort","comparisons",ablationComparisons));
        Map<String,Object> traceData=Json.obj("schemaVersion",1,"modeled",true,"selection","First4 profiles, repetition0, early levels/U11/blocked/Focus decisions; maximum100 per scenario,300 total; not a representative sample","traces",traces);
        Json.write(c.output.resolve("summary.json"),summary);Json.write(c.output.resolve("profiles.json"),profileData);Json.write(c.output.resolve("paired-comparisons.json"),paired);Json.write(c.output.resolve("traces.json"),traceData);
        Json.write(c.output.resolve("report.json"),Json.obj("schemaVersion",1,"summary",summary,"profiles",profileData,"pairedComparisons",paired,"traces",traceData));
        Map<String,Object> files=new TreeMap<>();try(java.util.stream.Stream<Path> paths=Files.list(c.output)){for(Path p:(Iterable<Path>)paths.filter(Files::isRegularFile).filter(p->!p.getFileName().toString().equals("provenance.json"))::iterator)files.put(p.getFileName().toString(),Json.obj("sha256",sha(p),"bytes",Files.size(p)));}
        Json.write(c.output.resolve("provenance.json"),Json.obj("schemaVersion",1,"seed",c.seed,"deterministicPayloads",true,"modelClock","Day0 at arbitrary modeled18:00; days are indices, no real calendar timestamps","runtime",Json.obj("elapsedSeconds",(System.nanoTime()-started)/1e9,"javaVersion",System.getProperty("java.version"),"os",System.getProperty("os.name"),"processors",Runtime.getRuntime().availableProcessors()),"sourceSha256",sourceHashes(c),"outputs",files,"rawData","CSV gzip streams have stable deterministic headers; decompress with gzip -dc. Main trajectories/attempts only; matched controls summarized separately."));
        System.out.println("Cognitive lab ready: "+c.output.toAbsolutePath()+" (all behavioral metrics modeled)");
    }
}
